from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    trie: list[dict[str, int]] = [{}]
    bad: list[bool] = [False]

    for word in banned:
        node = 0
        for ch in word:
            nxt = trie[node].get(ch)
            if nxt is None:
                nxt = len(trie)
                trie[node][ch] = nxt
                trie.append({})
                bad.append(False)
            node = nxt
        bad[node] = True

    fail = [0] * len(trie)
    queue: deque[int] = deque()

    for ch in alphabet:
        nxt = trie[0].get(ch)
        if nxt is not None:
            fail[nxt] = 0
            queue.append(nxt)
        else:
            trie[0][ch] = 0

    while queue:
        u = queue.popleft()
        fu = fail[u]
        if bad[fu]:
            bad[u] = True
        for ch in alphabet:
            v = trie[u].get(ch)
            if v is not None:
                fail[v] = trie[fu][ch]
                queue.append(v)
            else:
                trie[u][ch] = trie[fu][ch]

    safe_idx = [-1] * len(trie)
    k = 0
    for i, is_bad in enumerate(bad):
        if not is_bad:
            safe_idx[i] = k
            k += 1

    mat = [[0] * k for _ in range(k)]
    for u, ui in enumerate(safe_idx):
        if ui == -1:
            continue
        row = mat[ui]
        transitions = trie[u]
        for ch in alphabet:
            vi = safe_idx[transitions[ch]]
            if vi != -1:
                row[vi] += 1

    vec = [0] * k
    vec[safe_idx[0]] = 1

    exp = n
    while exp > 0:
        if exp & 1:
            new_vec = [0] * k
            for i in range(k):
                vi = vec[i]
                if vi:
                    row = mat[i]
                    for j in range(k):
                        new_vec[j] = (new_vec[j] + vi * row[j]) % MOD
            vec = new_vec
        exp >>= 1
        if exp > 0:
            new_mat = [[0] * k for _ in range(k)]
            for i in range(k):
                row_i = mat[i]
                res_i = new_mat[i]
                for m in range(k):
                    a = row_i[m]
                    if a:
                        row_m = mat[m]
                        for j in range(k):
                            res_i[j] = (res_i[j] + a * row_m[j]) % MOD
            mat = new_mat

    return sum(vec) % MOD
